/* ============================================================================
 * PHX — workspace icon loader  (the hand-written half; data is baked above)
 * Drop one tag on any page:   <script src="/tools/icons/icons.js"></script>
 * Then anywhere:              <i data-icon="shotkit"></i>
 * Optional:                   data-weight="duotone|bold|regular"  data-size="20"
 * Icons inherit text color (currentColor) and scale with font-size by default.
 * Source of truth = icon-map.json. Never hand-edit icons.js — run build.py.
 * ==========================================================================*/
(function () {
  var DATA = window.PHX_DATA || { map: {}, icons: {}, weightDefault: "regular" };
  var ATTR = "data-icon";

  function buildSvg(name, opts) {
    opts = opts || {};
    var glyph = DATA.map[name];
    if (!glyph) {
      if (!buildSvg._warned) { buildSvg._warned = {}; }
      if (!buildSvg._warned[name]) {
        buildSvg._warned[name] = 1;
        console.warn("[PHX] unknown icon: " + name + " — add it to icon-map.json + run build.py");
      }
      return "";
    }
    var weight = opts.weight || DATA.weightDefault || "regular";
    var entry = DATA.icons[glyph] || {};
    var inner = entry[weight] || entry.regular || "";
    if (!inner) return "";
    var size = opts.size ? (String(opts.size).match(/[a-z%]/i) ? opts.size : opts.size + "px") : "1em";
    var label = opts.label || glyph.replace(/-/g, " ");
    return (
      '<svg class="ph-icon" viewBox="0 0 256 256" width="' + size + '" height="' + size + '"' +
      ' fill="currentColor" role="img" aria-label="' + label + '" ' +
      'xmlns="http://www.w3.org/2000/svg">' + inner + "</svg>"
    );
  }

  function renderEl(el) {
    if (el.getAttribute("data-ph-done") === "1") return;
    var name = el.getAttribute(ATTR);
    if (!name) return;
    var svg = buildSvg(name, {
      weight: el.getAttribute("data-weight") || undefined,
      size: el.getAttribute("data-size") || undefined,
      label: el.getAttribute("aria-label") || undefined
    });
    if (svg) {
      el.innerHTML = svg;
      el.setAttribute("data-ph-done", "1");
      el.classList.add("ph");
    }
  }

  function render(root) {
    (root || document).querySelectorAll("[" + ATTR + "]").forEach(renderEl);
  }

  // ---- emoji -> icon auto-swap (opt-in) -------------------------------------
  // Build a reverse lookup from the baked meta: exact emoji string -> icon name.
  var EMO = [];
  var meta = DATA.meta || {};
  Object.keys(meta).forEach(function (name) {
    var e = meta[name] && meta[name].emoji;
    if (e) EMO.push([e, name]);
  });
  EMO.sort(function (a, b) { return b[0].length - a[0].length; }); // longest first
  var SKIP = { SCRIPT: 1, STYLE: 1, TEXTAREA: 1, CODE: 1, PRE: 1 };

  function deEmoji(root) {
    if (!EMO.length) return;
    root = root || document.body;
    var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null);
    var hits = [], node;
    while ((node = walker.nextNode())) {
      var p = node.parentNode;
      if (!p || SKIP[p.nodeName] || p.closest("[data-icon]")) continue;
      var t = node.nodeValue;
      for (var i = 0; i < EMO.length; i++) {
        if (t.indexOf(EMO[i][0]) !== -1) { hits.push(node); break; }
      }
    }
    hits.forEach(function (n) {
      var frag = document.createDocumentFragment();
      var rest = n.nodeValue, guard = 0;
      while (rest && guard++ < 400) {
        var best = -1, bestEmo = null, bestName = null;
        for (var i = 0; i < EMO.length; i++) {
          var idx = rest.indexOf(EMO[i][0]);
          if (idx !== -1 && (best === -1 || idx < best)) { best = idx; bestEmo = EMO[i][0]; bestName = EMO[i][1]; }
        }
        if (best === -1) { frag.appendChild(document.createTextNode(rest)); break; }
        if (best > 0) frag.appendChild(document.createTextNode(rest.slice(0, best)));
        var ic = document.createElement("i");
        ic.setAttribute("data-icon", bestName);
        renderEl(ic);
        frag.appendChild(ic);
        rest = rest.slice(best + bestEmo.length);
      }
      n.parentNode.replaceChild(frag, n);
    });
  }

  // Public API: PHX.render(root) re-scans, PHX.svg(name,opts) returns a string.
  window.PHX = {
    render: render,
    svg: buildSvg,
    deEmoji: deEmoji,
    map: DATA.map,
    meta: meta,
    weightDefault: DATA.weightDefault,
    setWeight: function (w) { DATA.weightDefault = w; }
  };

  // Minimal base style so icons sit on the text baseline everywhere (no css link needed).
  function injectStyle() {
    if (document.getElementById("ph-base-style")) return;
    var s = document.createElement("style");
    s.id = "ph-base-style";
    s.textContent =
      "[data-icon]{display:inline-flex;align-items:center;justify-content:center}" +
      ".ph-icon{display:inline-block;vertical-align:-0.15em;flex:none}";
    (document.head || document.documentElement).appendChild(s);
  }

  // Auto-render on load, then watch for icons added later (data-driven pages).
  function start() {
    injectStyle();
    render(document);
    // opt-in: <body data-deemoji> converts literal emoji -> icons automatically
    if (document.body && document.body.hasAttribute("data-deemoji")) deEmoji(document.body);
    if (window.MutationObserver) {
      var mo = new MutationObserver(function (muts) {
        if (mo._busy) return;            // ignore the mutations our own injection causes
        mo._busy = true;
        try {
          var deemoji = document.body && document.body.hasAttribute("data-deemoji");
          for (var i = 0; i < muts.length; i++) {
            var added = muts[i].addedNodes;
            for (var j = 0; j < added.length; j++) {
              var n = added[j];
              if (n.nodeType !== 1) continue;
              if (n.hasAttribute && n.hasAttribute(ATTR)) renderEl(n);
              if (n.querySelectorAll) render(n);
              if (deemoji) deEmoji(n);   // data-driven re-renders get de-emoji'd too
            }
          }
        } finally { mo._busy = false; }
      });
      mo.observe(document.documentElement, { childList: true, subtree: true });
    }
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", start);
  } else {
    start();
  }
})();
